const raw = $input.first().json;
const d   = raw.body || raw;

const amount    = 99;
const gst       = parseFloat((amount * 18 / 118).toFixed(2));
const subTotal  = parseFloat((amount - gst).toFixed(2));

const now            = new Date();
const invoiceDateFmt = now.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
const invoiceNumber  = 'YFB-BC-' + Date.now();

const LOGO_URL = 'https://yellowfeather.netlify.app/logo-landscape.png';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Invoice ${invoiceNumber}</title>
<style>
  body { font-family: Arial, sans-serif; background: #f4f4f4; margin: 0; padding: 0; }
  .wrapper { max-width: 680px; margin: 32px auto; background: #fff; border-radius: 10px; overflow: hidden; box-shadow: 0 2px 16px rgba(0,0,0,0.10); }
  .header { background: #1a1a2e; padding: 28px 40px; display: flex; align-items: center; justify-content: space-between; }
  .header img { height: 52px; object-fit: contain; }
  .inv-label { text-align: right; color: #aaa; font-size: 12px; }
  .inv-label strong { color: #F5B800; font-size: 18px; display: block; }
  .body { padding: 36px 40px; }
  .thank-you { font-size: 22px; font-weight: 700; color: #1a1a2e; margin-bottom: 4px; }
  .subtitle { color: #666; font-size: 14px; margin-bottom: 28px; line-height: 1.6; }
  .meta-row { display: flex; gap: 40px; margin-bottom: 28px; flex-wrap: wrap; }
  .meta-block label { font-size: 11px; color: #999; text-transform: uppercase; letter-spacing: 0.5px; display: block; margin-bottom: 3px; }
  .meta-block span { font-size: 14px; color: #1a1a2e; font-weight: 600; }
  table { width: 100%; border-collapse: collapse; font-size: 14px; margin-bottom: 24px; }
  thead tr { background: #1a1a2e; color: #fff; }
  thead th { padding: 11px 14px; text-align: left; font-weight: 600; font-size: 13px; }
  tbody tr:nth-child(even) { background: #f9f7f2; }
  tbody td { padding: 11px 14px; color: #333; border-bottom: 1px solid #eee; }
  .total-row td { background: #C9922A !important; color: #fff !important; font-weight: 700; font-size: 15px; border: none; }
  .payment-ref { background: #f5f0e8; border-left: 4px solid #C9922A; padding: 12px 16px; border-radius: 4px; font-size: 13px; color: #444; margin-bottom: 24px; }
  .payment-ref code { font-family: monospace; color: #1a1a2e; font-weight: 700; }
  .benefits { background: #f9f7f2; border-radius: 8px; padding: 16px 20px; margin-bottom: 24px; }
  .benefits h4 { font-size: 13px; color: #1a1a2e; margin-bottom: 10px; font-weight: 700; }
  .benefits ul { margin: 0; padding-left: 18px; font-size: 13px; color: #555; line-height: 2; }
  .message { font-size: 13px; color: #555; line-height: 1.75; margin-bottom: 28px; }
  .footer { background: #f5f0e8; padding: 18px 40px; text-align: center; font-size: 11px; color: #888; border-top: 1px solid #e5e0d8; }
  .footer a { color: #C9922A; text-decoration: none; }
</style>
</head>
<body>
<div class="wrapper">
  <div class="header">
    <img src="${LOGO_URL}" alt="Yellow Feather Books" />
    <div class="inv-label"><strong>INVOICE</strong>${invoiceNumber}<br/>${invoiceDateFmt}</div>
  </div>
  <div class="body">
    <div class="thank-you">Welcome to the Book Club! 📚</div>
    <div class="subtitle">Thank you for joining the Yellow Feather Book Club, <strong>${d.name}</strong>!<br/>This is a one-time membership fee of ₹99. Your lifetime membership is now active.</div>
    <div class="meta-row">
      <div class="meta-block"><label>Member Name</label><span>${d.name}</span></div>
      <div class="meta-block"><label>Email</label><span>${d.email}</span></div>
      <div class="meta-block"><label>Membership Type</label><span>Lifetime</span></div>
    </div>
    <table>
      <thead><tr><th>Description</th><th style="text-align:right">Amount (INR)</th></tr></thead>
      <tbody>
        <tr><td>Yellow Feather Book Club — Lifetime Membership (One-time fee)</td><td style="text-align:right">₹${subTotal.toFixed(2)}</td></tr>
        <tr><td>GST @ 18% (inclusive)</td><td style="text-align:right">₹${gst.toFixed(2)}</td></tr>
        <tr class="total-row"><td>Total Paid</td><td style="text-align:right">₹${amount.toFixed(2)}</td></tr>
      </tbody>
    </table>
    <div class="payment-ref">Razorpay Payment ID: <code>${d.razorpay_payment_id}</code> &nbsp;·&nbsp; Invoice Ref: <code>${invoiceNumber}</code></div>
    <div class="benefits">
      <h4>Your Book Club Benefits</h4>
      <ul>
        <li>Priority access to new arrivals</li>
        <li>Exclusive member discounts on all books</li>
        <li>Early access to author events &amp; book launches</li>
        <li>Monthly curated reading recommendations</li>
        <li>Access to the Yellow Feather community</li>
      </ul>
    </div>
    <div class="message">You can now log in to <a href="https://yellowfeather.netlify.app" style="color:#C9922A;">yellowfeather.netlify.app</a> with your email and password to start exploring.<br/><br/>For any queries, reach us at <a href="mailto:bookstore@yellowfeatherbookstore.com" style="color:#C9922A;">bookstore@yellowfeatherbookstore.com</a>.</div>
  </div>
  <div class="footer">Yellow Feather Books &nbsp;·&nbsp; <a href="mailto:bookstore@yellowfeatherbookstore.com">bookstore@yellowfeatherbookstore.com</a> &nbsp;·&nbsp; +91 96056 89946</div>
</div>
</body>
</html>`;

return [{ json: { ...d, invoiceHtml: html, invoiceNumber } }];
